판 = [[7, 2, 9],
      [4, 5, 1],
      [8, 3, 6]]
while True:
    답 = input("부른 수: ")
    if 답 == "끝":
        break
    수 = int(답)
    for 줄 in range(3):
        for 칸 in range(3):
            if 판[줄][칸] == 수:
                판[줄][칸] = "X"
for 한줄 in 판:
    for 값 in 한줄:
        print(값, end=" ")
    print()
빙고 = 0
for 줄 in range(3):
    개수 = 0
    for 칸 in range(3):
        if 판[줄][칸] == "X":
            개수 += 1
    if 개수 == 3:
        빙고 += 1
for 칸 in range(3):
    개수 = 0
    for 줄 in range(3):
        if 판[줄][칸] == "X":
            개수 += 1
    if 개수 == 3:
        빙고 += 1
print("빙고", 빙고, "줄")
